531	/// Canonical byte encoding of the authenticated content.
532	///
533	/// Layout (all integers big-endian, all text UTF-8, no trimming or escaping):
534	///   DOMAIN_SEPARATOR ("authnote-sign-v1", 16 ASCII bytes)
535	///   u64 length of key-id, then key-id bytes
536	///   u32 key version
537	///   u64 field count
538	///   for each field in order: u64 length of field, then field bytes
539	///
540	/// Length prefixes make field boundaries unambiguous: ["ab","c"] and
541	/// ["a","bc"] encode differently, as do zero fields and one empty field.
542	fn encode_message(key_id: &str, key_version: u32, fields: &[String]) -> Vec<u8> {
543	    let mut out = Vec::new();
544	    out.extend_from_slice(DOMAIN_SEPARATOR);
545	    push_len_prefixed(&mut out, key_id.as_bytes());
546	    out.extend_from_slice(&key_version.to_be_bytes());
547	    out.extend_from_slice(&(fields.len() as u64).to_be_bytes());
548	    for field in fields {
549	        push_len_prefixed(&mut out, field.as_bytes());
550	    }
551	    out
552	}
553	
554	fn push_len_prefixed(out: &mut Vec<u8>, bytes: &[u8]) {
555	    out.extend_from_slice(&(bytes.len() as u64).to_be_bytes());
556	    out.extend_from_slice(bytes);
557	}
558	
559	fn decode_hex(s: &str) -> Result<Vec<u8>, String> {
560	    (0..s.len())
561	        .step_by(2)
562	        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).map_err(|e| e.to_string()))
563	        .collect()
564	}
565	
566	fn hex_encode(bytes: &[u8]) -> String {
567	    bytes.iter().map(|b| format!("{b:02x}")).collect()
568	}
569	
570	fn json_escape(s: &str) -> String {
571	    let mut out = String::with_capacity(s.len());
572	    for c in s.chars() {
573	        match c {
574	            '"' => out.push_str("\\\""),
575	            '\\' => out.push_str("\\\\"),
576	            '\n' => out.push_str("\\n"),
577	            '\r' => out.push_str("\\r"),
578	            '\t' => out.push_str("\\t"),
579	            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
580	            c => out.push(c),
581	        }
582	    }
583	    out
584	}
