1000	    /// Build a format-1 record JSON string for the given content, with the
1001	    /// correct tag for `key`.
1002	    fn record_for(key_hex: &str, key_id: &str, version: u32, fields: &[&str]) -> String {
1003	        let tag = sign_tag(key_hex, key_id, version, fields);
1004	        let fields_json = fields
1005	            .iter()
1006	            .map(|f| format!("\"{}\"", json_escape(f)))
1007	            .collect::<Vec<_>>()
1008	            .join(",");
1009	        format!(
1010	            "{{\"format\":1,\"algorithm\":\"HMAC-SHA256\",\"key_id\":\"{}\",\"key_version\":{},\"fields\":[{}],\"tag\":\"{}\"}}",
1011	            json_escape(key_id),
1012	            version,
1013	            fields_json,
1014	            tag
1015	        )
1016	    }
