1018	    #[test]
1019	    fn verify_accepts_valid_records() {
1020	        let key = "0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b";
1021	        // Zero fields vs one empty field are both valid and distinct.
1022	        assert!(matches!(
1023	            verify_input(record_for(key, "id", 1, &[]).as_bytes(), key),
1024	            VerifyOutcome::Valid
1025	        ));
1026	        assert!(matches!(
1027	            verify_input(record_for(key, "id", 1, &[""]).as_bytes(), key),
1028	            VerifyOutcome::Valid
1029	        ));
1030	        // Unicode, duplicate and reordered fields.
1031	        let rec = record_for(key, "demo", 3, &["hello", "世界", "世界"]);
1032	        assert!(matches!(verify_input(rec.as_bytes(), key), VerifyOutcome::Valid));
1033	        // Surrounding JSON whitespace and internal reformatting are fine.
1034	        let pretty = format!(
1035	            " \n\t{}  \r\n",
1036	            rec.replace(',', ",\n  ").replace('{', "{\n  ")
1037	        );
1038	        assert!(matches!(
1039	            verify_input(pretty.as_bytes(), key),
1040	            VerifyOutcome::Valid
1041	        ));
1042	        // Member order must not matter.
1043	        let reordered = "{\"tag\":\"X\",\"fields\":[],\"key_version\":1,\"key_id\":\"id\",\
1044	                         \"algorithm\":\"HMAC-SHA256\",\"format\":1}";
1045	        // Recompute with the real tag to keep this a positive case.
1046	        let mut reordered = reordered.to_string();
1047	        let tag = sign_tag(key, "id", 1, &[]);
1048	        reordered = reordered.replace('X', &tag);
1049	        assert!(matches!(
1050	            verify_input(reordered.as_bytes(), key),
1051	            VerifyOutcome::Valid
1052	        ));
1053	        // Uppercase tag spelling still represents the same 32 bytes.
1054	        let real_tag = sign_tag(key, "id", 1, &["x"]);
1055	        let upper = record_for(key, "id", 1, &["x"]).replace(&real_tag, &real_tag.to_uppercase());
1056	        assert!(matches!(
1057	            verify_input(upper.as_bytes(), key),
1058	            VerifyOutcome::Valid
1059	        ));
1060	    }
