1	//! End-to-end regression tests for the observable result of `authnote sign`.
2	//!
3	//! These tests execute the built binary and assert on the exact JSON record a
4	//! user receives on stdout/stderr, not just on intermediate HMAC values.
5	//!
6	//! Expected tags are *golden* values: each was computed independently with
7	//! Python's hmac/hashlib/struct straight from the format-1 byte contract in
8	//! README.md (domain separator `authnote-sign-v1`, big-endian u64/u32 length
9	//! prefixes, raw UTF-8 bytes), never derived from this crate's own HMAC code.
10	//! A change that breaks the byte encoding and the JSON output in the same way
11	//! therefore still fails these tests.
12	//!
13	//! The tests parse stdout with the small JSON parser below instead of pulling
14	//! in a third-party dependency, so `Cargo.toml` stays unchanged.
15	
16	use std::process::{Command, Output};
17	
18	// ---------------------------------------------------------------------------
19	// Test harness around the compiled binary.
20	// ---------------------------------------------------------------------------
21	
22	fn authnote() -> Command {
23	    Command::new(env!("CARGO_BIN_EXE_authnote"))
24	}
25	
26	/// Run `sign` with `--field` entries appended in the given order.
27	fn run_sign(key: &str, key_id: &str, version: &str, fields: &[&str]) -> Output {
28	    let mut cmd = authnote();
29	    cmd.arg("sign")
30	        .arg("--key")
31	        .arg(key)
32	        .arg("--key-id")
33	        .arg(key_id)
34	        .arg("--key-version")
35	        .arg(version);
36	    for f in fields {
37	        cmd.arg("--field").arg(f);
38	    }
39	    cmd.output().expect("failed to execute authnote")
40	}
41	
42	/// Run `sign` with a raw argument vector (for error-path cases).
43	fn run_sign_raw(args: &[&str]) -> Output {
44	    let mut cmd = authnote();
45	    cmd.arg("sign");
46	    for a in args {
47	        cmd.arg(a);
48	    }
49	    cmd.output().expect("failed to execute authnote")
50	}
51	
52	/// Run `verify --key <key>` feeding `input` to standard input.
53	fn run_verify(key: &str, input: &[u8]) -> Output {
54	    let mut cmd = authnote();
55	    cmd.arg("verify").arg("--key").arg(key);
56	    use std::io::Write;
57	    use std::process::Stdio;
58	    let mut child = cmd
59	        .stdin(Stdio::piped())
60	        .stdout(Stdio::piped())
61	        .stderr(Stdio::piped())
62	        .spawn()
63	        .expect("failed to spawn authnote");
64	    child
65	        .stdin
66	        .take()
67	        .unwrap()
68	        .write_all(input)
69	        .expect("failed to write record to stdin");
70	    child.wait_with_output().expect("failed to await authnote")
71	}
72	
73	/// Run `verify` with raw arguments and stdin (for option-error cases).
74	fn run_verify_raw(args: &[&str], input: &[u8]) -> Output {
75	    let mut cmd = authnote();
76	    cmd.arg("verify");
77	    for a in args {
78	        cmd.arg(a);
79	    }
80	    use std::io::Write;
81	    use std::process::Stdio;
82	    let mut child = cmd
83	        .stdin(Stdio::piped())
84	        .stdout(Stdio::piped())
85	        .stderr(Stdio::piped())
86	        .spawn()
87	        .expect("failed to spawn authnote");
88	    // Every caller here drives an error path that exits before reading stdin
89	    // (a malformed option), so the child may already be gone when we write; a
90	    // BrokenPipe then simply reflects that early exit and must not fail the
91	    // test. The outcome is still pinned by the exit code / stdout / stderr
92	    // assertions after reaping the child.
93	    if let Err(e) = child.stdin.take().unwrap().write_all(input) {
94	        assert_eq!(
95	            e.kind(),
96	            std::io::ErrorKind::BrokenPipe,
97	            "unexpected stdin write error: {e}"
98	        );
99	    }
100	    child.wait_with_output().expect("failed to await authnote")
101	}
102	
103	/// Sign a record and return its exact stdout bytes (including the newline).
104	fn sign_record_bytes(key: &str, key_id: &str, version: &str, fields: &[&str]) -> Vec<u8> {
105	    run_sign(key, key_id, version, fields).stdout
106	}
107	
108	// ---------------------------------------------------------------------------
109	// verify: success path
110	// ---------------------------------------------------------------------------
111	
112	#[test]
113	fn verify_accepts_the_record_sign_produces() {
114	    let key = "0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b";
115	    let record = sign_record_bytes(key, "demo", "3", &["hello", "世界"]);
116	    let out = run_verify(key, &record);
117	    assert_eq!(out.status.code(), Some(0));
118	    assert!(out.stderr.is_empty(), "stderr must be empty, got {:?}", String::from_utf8_lossy(&out.stderr));
119	    assert_eq!(out.stdout, b"{\"valid\":true}\n");
120	}
121	
122	#[test]
123	fn verify_tolerates_reserialization_reordering_and_whitespace() {
124	    let key = "00112233445566778899aabbccddeeff";
125	    let record = sign_record_bytes(key, "kid-名字", "7", &["中文🙂", "x y"]);
126	
127	    // Parse, then emit pretty JSON with members in reverse order.
128	    let body = std::str::from_utf8(&record).unwrap().trim_end_matches('\n');
129	    let parsed = Json::parse(body);
130	    let obj = parsed.as_object();
131	    let mut reordered = String::from("{\n");
132	    for (i, (k, v)) in obj.iter().rev().enumerate() {
133	        if i > 0 {
134	            reordered.push_str(",\n");
135	        }
136	        reordered.push_str(&format!("  {k:?}: "));
137	        reordered.push_str(&json_value_to_text(v));
138	    }
139	    reordered.push_str("\n}");
140	    let padded = format!("  \t\n{reordered}\r\n  ");
141	
142	    let out = run_verify(key, padded.as_bytes());
143	    assert_eq!(out.status.code(), Some(0), "stderr={:?}", String::from_utf8_lossy(&out.stderr));
144	    assert_eq!(out.stdout, b"{\"valid\":true}\n");
145	    assert!(out.stderr.is_empty());
146	}
147	
148	/// Render a parsed Json back into compact JSON (test helper; records contain
149	/// only objects/arrays/strings/integers).
150	fn json_value_to_text(v: &Json) -> String {
151	    fn escape(s: &str) -> String {
152	        let mut out = String::from("\"");
153	        for c in s.chars() {
154	            match c {
155	                '"' => out.push_str("\\\""),
156	                '\\' => out.push_str("\\\\"),
157	                '\n' => out.push_str("\\n"),
158	                '\r' => out.push_str("\\r"),
159	                '\t' => out.push_str("\\t"),
160	                c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
161	                c => out.push(c),
162	            }
163	        }
164	        out.push('"');
165	        out
166	    }
167	    match v {
168	        Json::Str(s) => escape(s),
169	        Json::Num(n) => n.to_string(),
170	        Json::Arr(a) => format!(
171	            "[{}]",
172	            a.iter().map(json_value_to_text).collect::<Vec<_>>().join(",")
173	        ),
174	        Json::Obj(o) => format!(
175	            "{{{}}}",
176	            o.iter()
177	                .map(|(k, v)| format!("{}:{}", escape(k), json_value_to_text(v)))
178	                .collect::<Vec<_>>().join(",")
179	        ),
180	        other => panic!("unexpected value {other:?}"),
181	    }
182	}
183	
184	#[test]
185	fn verify_distinct_encodings_and_unicode_escapes() {
186	    let key = "00ff";
187	    // Zero fields vs one empty field each verify with their own records.
188	    let zero = sign_record_bytes(key, "id", "1", &[]);
189	    let one_empty = sign_record_bytes(key, "id", "1", &[""]);
190	    assert_eq!(run_verify(key, &zero).status.code(), Some(0));
191	    assert_eq!(run_verify(key, &one_empty).status.code(), Some(0));
192	
193	    // A record whose Chinese text is written using \u escapes still verifies:
194	    // verification runs over the decoded text, not the raw JSON spelling.
195	    let rec = sign_record_bytes(key, "id", "1", &["世界"]);
196	    let body = std::str::from_utf8(&rec).unwrap();
197	    let escaped = body.replace("世界", "\\u4e16\\u754c");
198	    let out = run_verify(key, escaped.as_bytes());
199	    assert_eq!(out.status.code(), Some(0), "stderr={:?}", String::from_utf8_lossy(&out.stderr));
200	    assert_eq!(out.stdout, b"{\"valid\":true}\n");
201	
202	    // Uppercase tag hex is accepted and still yields valid.
203	    let body = String::from_utf8(rec).unwrap();
204	    let parsed = Json::parse(body.trim_end_matches('\n'));
205	    let upper_obj: Vec<(String, Json)> = parsed
206	        .as_object()
207	        .iter()
208	        .map(|(k, v)| {
209	            if k == "tag" {
210	                (k.clone(), Json::Str(v.as_str().to_uppercase()))
211	            } else {
212	                (k.clone(), v.clone())
213	            }
214	        })
215	        .collect();
216	    let rebuilt = json_value_to_text(&Json::Obj(upper_obj)) + "\n";
217	    let out = run_verify(key, rebuilt.as_bytes());
218	    assert_eq!(out.status.code(), Some(0));
219	}
