221	// ---------------------------------------------------------------------------
222	// verify: mismatch path (exit 1, {"valid":false})
223	// ---------------------------------------------------------------------------
224	
225	#[test]
226	fn verify_wrong_key_and_tampered_fields_exit_1() {
227	    let key = "0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b";
228	    let record = sign_record_bytes(key, "demo", "3", &["hello", "世界"]);
229	
230	    // Wrong key: structurally fine, just doesn't authenticate.
231	    let out = run_verify("0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0c", &record);
232	    assert_eq!(out.status.code(), Some(1));
233	    assert!(out.stderr.is_empty());
234	    assert_eq!(out.stdout, b"{\"valid\":false}\n");
235	
236	    // Tampered field content / key id / version: each keeps legal JSON.
237	    let body = std::str::from_utf8(&record).unwrap();
238	    let variants = [
239	        body.replace("hello", "hellp"),
240	        body.replace("\"demo\"", "\"demo2\""),
241	        body.replace("\"key_version\":3", "\"key_version\":4"),
242	    ];
243	    for rec_text in variants {
244	        let out = run_verify(key, rec_text.as_bytes());
245	        assert_eq!(
246	            out.status.code(),
247	            Some(1),
248	            "expected mismatch, stderr={:?}",
249	            String::from_utf8_lossy(&out.stderr)
250	        );
251	        assert_eq!(out.stdout, b"{\"valid\":false}\n");
252	        assert!(out.stderr.is_empty());
253	    }
254	}
