324	#[test]
325	fn verify_rejects_corrupt_and_ill_typed_records() {
326	    let key = "00ff";
327	    let bad: &[&[u8]] = &[
328	        b"{",
329	        b"[]",
330	        b"\"x\"",
331	        b"42",
332	        br#"{"format":1,"algorithm":"HMAC-SHA256","key_id":"id","key_version":1,"fields":["x"]}"#,
