843	// Record-level assertions shared by every success-path test.
844	// ---------------------------------------------------------------------------
845	
846	#[derive(Debug)]
847	struct Record {
848	    raw: Json,
849	    format: i64,
850	    algorithm: String,
851	    key_id: String,
852	    key_version: i64,
853	    fields: Vec<String>,
854	    tag: String,
855	}
