857	/// Parse the sole JSON record on stdout, enforcing the observable contract:
858	/// exactly one line, exactly the six documented keys in documented order,
859	/// format 1, fixed algorithm name, valid version range, 64 lowercase hex tag.
860	fn parse_single_record(stdout: &[u8]) -> Record {
861	    let text = std::str::from_utf8(stdout).expect("stdout must be valid UTF-8");
862	    assert!(text.starts_with('{'), "stdout must start with the JSON object");
863	    let body = text
864	        .strip_suffix('\n')
865	        .expect("stdout must end with exactly one newline");
866	    assert!(!body.is_empty(), "stdout must contain one JSON record");
867	    assert!(!body.contains('\n'), "stdout must contain exactly one line");
868	    assert!(!body.ends_with('\r'), "line must not carry a carriage return");
869	
870	    let raw = Json::parse(body);
871	    let keys: Vec<&str> = raw.as_object().iter().map(|(k, _)| k.as_str()).collect();
872	    assert_eq!(
873	        keys,
874	        vec![
875	            "format",
876	            "algorithm",
877	            "key_id",
878	            "key_version",
879	            "fields",
880	            "tag"
881	        ],
882	        "record field structure must stay compatible"
883	    );
884	
885	    let fields = raw
886	        .get("fields")
887	        .as_array()
888	        .iter()
889	        .map(|v| v.as_str().to_string())
890	        .collect();
891	
892	    let rec = Record {
893	        format: raw.get("format").as_i64(),
894	        algorithm: raw.get("algorithm").as_str().to_string(),
895	        key_id: raw.get("key_id").as_str().to_string(),
896	        key_version: raw.get("key_version").as_i64(),
897	        fields,
898	        tag: raw.get("tag").as_str().to_string(),
899	        raw,
