920	/// Successful invocation: exit code 0, empty stderr, one valid record whose
921	/// fields/key-id/version match the inputs and whose tag equals the golden
922	/// value computed independently of this implementation.
923	fn expect_signed_record(
924	    label: &str,
925	    key: &str,
926	    key_id: &str,
927	    version: &str,
928	    fields: &[&str],
929	    golden_tag: &str,
930	) -> Record {
931	    let out = run_sign(key, key_id, version, fields);
932	    assert_eq!(
933	        out.status.code(),
934	        Some(0),
935	        "{label}: expected exit 0, got {:?}, stderr={:?}",
936	        out.status.code(),
937	        String::from_utf8_lossy(&out.stderr)
938	    );
939	    assert!(
940	        out.stderr.is_empty(),
941	        "{label}: stderr must be empty, got {:?}",
942	        String::from_utf8_lossy(&out.stderr)
943	    );
944	
945	    let rec = parse_single_record(&out.stdout);
946	    assert_eq!(rec.tag, golden_tag, "{label}: tag mismatch");
947	    assert_eq!(rec.key_id, key_id, "{label}: key_id mismatch");
948	    assert_eq!(
949	        rec.key_version,
950	        version.parse::<i64>().unwrap(),
951	        "{label}: key_version mismatch"
952	    );
953	    assert_eq!(
954	        rec.fields,
955	        fields.iter().map(|s| s.to_string()).collect::<Vec<_>>(),
956	        "{label}: parsed fields must be character-identical to the inputs"
957	    );
958	
959	    // The raw key is used only for the MAC: it must never appear as a value
960	    // anywhere in the record (compared as a whole string, not a substring, so
961	    // short keys cannot clash with random fragments of the 64-char tag).
962	    let needle = key.to_lowercase();
963	    let mut strings = Vec::new();
964	    rec.raw.strings(&mut strings);
965	    assert!(
966	        strings.iter().all(|s| s.to_lowercase() != needle),
967	        "{label}: raw key material must not be part of the record"
968	    );
969	    rec
970	}
