fn verify_reports_unsupported_format_and_algorithm_explicitly() {
    let key = "00ff";
    let tag = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
    let f2 = format!(
