        ("single-ab", "00ff", "id", "1", &["ab"],
            "c4e0c0326796572ca45896897a0fafb9dcf17d2b5078dc241b0ff5c3a71ec8a9"),
        ("multibyte-max-version", "deadbeef", "id", "4294967295", &["世界🙂"],
