        ("dup-x-x", "0102", "id", "1", &["x", "x"],
            "9dc97338f638b83cc7d245e798a0ee1b54596321356b5595b9a83a1f750c8856"),
        ("single-x-0102", "0102", "id", "1", &["x"],
            "9b326498fb6eb680d2790d03c72fdc548767d65e9aef2d20a5b817c58a802bdc"),
        ("order-a-b", "0102", "id", "1", &["a", "b"],
